import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_me, last_op = history[-1]

    if n < 10:
        return 'C'

    op_defects = 0
    for i in range(max(0, n - 12), n):
        if history[i][1] == 'D':
            op_defects += 1

    if op_defects == 0:
        if n >= 190:
            return 'D' if n % 2 == 0 else 'C'
        return 'C'

    if op_defects >= 9:
        return 'D'

    if op_defects >= 5:
        return 'D' if rng.random() < 0.75 else 'C'

    if last_op == 'D':
        me_defects = 0
        for i in range(max(0, n - 12), n):
            if history[i][0] == 'D':
                me_defects += 1
        if me_defects >= 3:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'D'

    return 'C'

